  1→import { useState, useEffect } from "react";
  2→import { useQuery, useQueryClient } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { useAuth } from "@/hooks/useAuth";
  5→import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
  6→import { Button } from "@/components/ui/button";
  7→import { Textarea } from "@/components/ui/textarea";
  8→import { Input } from "@/components/ui/input";
  9→import { Label } from "@/components/ui/label";
 10→import { Slider } from "@/components/ui/slider";
 11→import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
 12→import { Badge } from "@/components/ui/badge";
 13→import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
 14→import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
 15→import { ScrollArea } from "@/components/ui/scroll-area";
 16→import { toast } from "sonner";
 17→import { RotateCcw, Save, Loader2, Plus, Play, History, GitCompare, Star, Trash2 } from "lucide-react";
 18→
 19→const PROMPT_TYPES = [
 20→  { key: "jd_analysis", label: "JD Analysis" },
 21→  { key: "resume_parse", label: "Resume Parse" },
 22→  { key: "deep_scoring", label: "Deep Scoring" },
 23→] as const;
 24→
 25→type PromptType = typeof PROMPT_TYPES[number]["key"];
 26→
 27→const DEFAULT_PROMPTS: Record<PromptType, string> = {
 28→  jd_analysis: `You are an expert recruiter. Analyze a job description and extract structured intelligence including role_type, seniority, domain, critical_must_haves, preferred_must_haves, nice_to_have, tools, evaluation_dimensions with rubrics. Return ONLY valid JSON.`,
 29→  resume_parse: `You are an expert resume parser. Extract structured data: candidate_name, skills_with_evidence, roles_with_dates, projects, tools, education, certifications, domain_experience, leadership_signals. Return ONLY valid JSON.`,
 30→  deep_scoring: `You are an expert recruiter performing deep candidate evaluation. Score each evaluation dimension 0-100 using the provided rubric. Return hard_fit, category_scores, strengths, gaps, interview_questions, explanation, confidence. Return ONLY valid JSON.`,
 31→};
 32→
 33→const SAMPLE_INPUTS: Record<PromptType, string> = {
 34→  jd_analysis: `Senior Full-Stack Engineer - FinTech\nWe need a senior engineer with 5+ years experience in React, Node.js, and PostgreSQL. Must have experience with payment systems. Nice to have: AWS, Docker, GraphQL. Remote-friendly.`,
 35→  resume_parse: `John Doe\nSenior Software Engineer\n5 years at TechCorp building React/Node apps.\nSkills: React, TypeScript, Node.js, PostgreSQL, AWS\nBS Computer Science, MIT 2018`,
 36→  deep_scoring: `Evaluate this candidate against the job requirements:\nCandidate has 5 years React experience, strong Node.js, basic PostgreSQL.\nJob requires: 5+ years React, Node.js, PostgreSQL, payment systems experience.\nCandidate has no payment systems experience.`,
 37→};
 38→
 39→interface PromptVersion {
 40→  id: string;
 41→  prompt_type: string;
 42→  label: string;
 43→  prompt_text: string;
 44→  model: string;
 45→  temperature: number;
 46→  is_active: boolean;
 47→  test_result_json: any;
 48→  notes: string;
 49→  created_at: string;
 50→}
 51→
 52→interface RankingConfig {
 53→  id: string;
 54→  model: string;
 55→  temperature: number;
 56→  max_resume_chars: number;
 57→  num_interview_questions: number;
 58→  jd_analysis_prompt: string;
 59→  resume_parse_prompt: string;
 60→  deep_scoring_prompt: string;
 61→  default_weight_strategy: string;
 62→  weight_overrides_json: Record<string, number>;
 63→  hard_fit_cap: number;
 64→  min_text_length: number;
 65→  min_word_ratio: number;
 66→  algorithm_version: number;
 67→  updated_at: string;
 68→}
 69→
 70→const AIPromptsTab = () => {
 71→  const { user } = useAuth();
 72→  const qc = useQueryClient();
 73→  const [config, setConfig] = useState<RankingConfig | null>(null);
 74→  const [loading, setLoading] = useState(true);
 75→  const [saving, setSaving] = useState(false);
 76→  const [activeTab, setActiveTab] = useState<"config" | "studio" | "algorithm">("config");
 77→  const [studioType, setStudioType] = useState<PromptType>("jd_analysis");
 78→  const [showHistory, setShowHistory] = useState(false);
 79→  const [compareIds, setCompareIds] = useState<[string, string] | null>(null);
 80→  const [testInput, setTestInput] = useState("");
 81→  const [testingId, setTestingId] = useState<string | null>(null);
 82→  const [newVersionDialog, setNewVersionDialog] = useState(false);
 83→  const [newForm, setNewForm] = useState({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
 84→
 85→  useEffect(() => { fetchConfig(); }, []);
 86→
 87→  const fetchConfig = async () => {
 88→    const { data, error } = await supabase
 89→      .from("ranking_config")
 90→      .select("*")
 91→      .limit(1).single();
 92→    if (error) toast.error("Error loading config: " + error.message);
 93→    else setConfig(data as unknown as RankingConfig);
 94→    setLoading(false);
 95→  };
 96→
 97→  const { data: versions, isLoading: versionsLoading } = useQuery({
 98→    queryKey: ["prompt_versions", studioType],
 99→    queryFn: async () => {
100→      const { data, error } = await supabase
101→        .from("prompt_versions")
102→        .select("*")
103→        .eq("prompt_type", studioType)
104→        .order("created_at", { ascending: false });
105→      if (error) throw error;
106→      return data as PromptVersion[];
107→    },
108→  });
109→
110→  const handleSaveConfig = async () => {
111→    if (!config) return;
112→    setSaving(true);
113→    const { id, updated_at, ...updates } = config;
114→    const { error } = await supabase.from("ranking_config").update(updates as any).eq("id", id);
115→    setSaving(false);
116→    if (error) toast.error(error.message);
117→    else { toast.success("Configuration saved"); fetchConfig(); }
118→  };
119→
120→  const handleResetConfig = () => {
121→    if (!config) return;
122→    setConfig({
123→      ...config, model: "gpt-4o-mini", temperature: 0.2, max_resume_chars: 4000, num_interview_questions: 5,
124→      jd_analysis_prompt: DEFAULT_PROMPTS.jd_analysis,
125→      resume_parse_prompt: DEFAULT_PROMPTS.resume_parse,
126→      deep_scoring_prompt: DEFAULT_PROMPTS.deep_scoring,
127→    });
128→  };
129→
130→  const updateConfig = (field: keyof RankingConfig, value: any) => {
131→    if (config) setConfig({ ...config, [field]: value });
132→  };
133→
134→  const createVersion = async () => {
135→    if (!newForm.label || !newForm.prompt_text) { toast.error("Label and prompt text are required"); return; }
136→    const { error } = await supabase.from("prompt_versions").insert({
137→      prompt_type: studioType,
138→      label: newForm.label,
139→      prompt_text: newForm.prompt_text,
140→      model: newForm.model,
141→      temperature: newForm.temperature,
142→      notes: newForm.notes,
143→      created_by: user?.id,
144→    } as any);
145→    if (error) { toast.error(error.message); return; }
146→    toast.success("Version created");
147→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
148→    setNewVersionDialog(false);
149→    setNewForm({ label: "", prompt_text: "", model: "gpt-4o-mini", temperature: 0.2, notes: "" });
150→  };
151→
152→  const activateVersion = async (v: PromptVersion) => {
153→    // Deactivate all, activate selected
154→    await supabase.from("prompt_versions").update({ is_active: false } as any).eq("prompt_type", studioType);
155→    await supabase.from("prompt_versions").update({ is_active: true } as any).eq("id", v.id);
156→
157→    // Also update ranking_config with this prompt
158→    const promptField = `${studioType}_prompt` as keyof RankingConfig;
159→    if (config) {
160→      await supabase.from("ranking_config").update({
161→        [promptField]: v.prompt_text,
162→        model: v.model,
163→        temperature: v.temperature,
164→      } as any).eq("id", config.id);
165→      fetchConfig();
166→    }
167→    toast.success(`"${v.label}" activated and deployed`);
168→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
169→  };
170→
171→  const testVersion = async (v: PromptVersion) => {
172→    const input = testInput || SAMPLE_INPUTS[studioType];
173→    setTestingId(v.id);
174→    try {
175→      const { data, error } = await supabase.functions.invoke("test-prompt", {
176→        body: { prompt_text: v.prompt_text, model: v.model, temperature: v.temperature, sample_input: input },
177→      });
178→      if (error) throw error;
179→      // Save test result
180→      await supabase.from("prompt_versions").update({ test_result_json: data } as any).eq("id", v.id);
181→      qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
182→      toast.success(`Test complete (${data.latency_ms}ms, ${data.tokens.total_tokens} tokens)`);
183→    } catch (err: any) {
184→      toast.error("Test failed: " + err.message);
185→    }
186→    setTestingId(null);
187→  };
188→
189→  const deleteVersion = async (v: PromptVersion) => {
190→    if (!confirm(`Delete version "${v.label}"?`)) return;
191→    await supabase.from("prompt_versions").delete().eq("id", v.id);
192→    qc.invalidateQueries({ queryKey: ["prompt_versions", studioType] });
193→    toast.success("Version deleted");
194→  };
195→
196→  const openNewFromCurrent = () => {
197→    const promptField = `${studioType}_prompt` as keyof RankingConfig;
198→    setNewForm({
199→      label: `v${(versions?.length ?? 0) + 1}`,
200→      prompt_text: (config?.[promptField] as string) || DEFAULT_PROMPTS[studioType],
201→      model: config?.model || "gpt-4o-mini",
202→      temperature: config?.temperature ?? 0.2,
203→      notes: "",
204→    });
205→    setNewVersionDialog(true);
206→  };
207→
208→  const compareVersions = versions?.filter((v) => compareIds?.includes(v.id)) ?? [];
209→
210→  if (loading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading…</div>;
211→  if (!config) return <div className="text-destructive">No ranking config found.</div>;
212→
213→  return (
214→    <div className="space-y-6">
215→      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as any)}>
216→        <div className="flex items-center justify-between">
217→          <TabsList>
218→            <TabsTrigger value="config">Live Configuration</TabsTrigger>
219→            <TabsTrigger value="studio">Prompt Studio</TabsTrigger>
220→            <TabsTrigger value="algorithm">Scoring Algorithm</TabsTrigger>
221→          </TabsList>
222→          {activeTab === "config" && (
223→            <div className="flex gap-2">
224→              <Button variant="outline" size="sm" onClick={handleResetConfig}><RotateCcw className="h-4 w-4 mr-1" />Reset</Button>
225→              <Button size="sm" onClick={handleSaveConfig} disabled={saving}>
226→                {saving ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}Save
227→              </Button>
228→            </div>
229→          )}
230→        </div>
231→
232→        {/* ── Live Configuration Tab ── */}
233→        <TabsContent value="config" className="space-y-6 max-w-3xl">
234→          <Card>
235→            <CardHeader><CardTitle className="text-lg">Model Settings</CardTitle></CardHeader>
236→            <CardContent className="space-y-4">
237→              <div className="grid grid-cols-2 gap-4">
238→                <div className="space-y-2">
239→                  <Label>Model</Label>
240→                  <Select value={config.model} onValueChange={(v) => updateConfig("model", v)}>
241→                    <SelectTrigger><SelectValue /></SelectTrigger>
242→                    <SelectContent>
243→                      <SelectItem value="gpt-4o-mini">gpt-4o-mini</SelectItem>
244→                      <SelectItem value="gpt-4o">gpt-4o</SelectItem>
245→                      <SelectItem value="gpt-4-turbo">gpt-4-turbo</SelectItem>
246→                    </SelectContent>
247→                  </Select>
248→                </div>
249→                <div className="space-y-2">
250→                  <Label>Interview Questions</Label>
251→                  <Input type="number" min={1} max={20} value={config.num_interview_questions} onChange={(e) => updateConfig("num_interview_questions", parseInt(e.target.value) || 5)} />
252→                </div>
253→              </div>
254→              <div className="space-y-2">
255→                <div className="flex justify-between"><Label>Temperature</Label><span className="text-sm text-muted-foreground">{config.temperature}</span></div>
256→                <Slider value={[config.temperature]} onValueChange={([v]) => updateConfig("temperature", Math.round(v * 100) / 100)} min={0} max={1} step={0.05} />
257→              </div>
258→              <div className="space-y-2">
259→                <Label>Max Resume Characters</Label>
260→                <Input type="number" min={1000} max={16000} step={500} value={config.max_resume_chars} onChange={(e) => updateConfig("max_resume_chars", parseInt(e.target.value) || 4000)} />
261→              </div>
262→            </CardContent>
263→          </Card>
264→
265→          {PROMPT_TYPES.map(({ key, label }) => (
266→            <Card key={key}>
267→              <CardHeader>
268→                <CardTitle className="text-lg">{label} Prompt</CardTitle>
269→              </CardHeader>
270→              <CardContent>
271→                <Textarea
272→                  value={(config as any)[`${key}_prompt`] || ""}
273→                  onChange={(e) => updateConfig(`${key}_prompt` as any, e.target.value)}
274→                  rows={6} className="font-mono text-xs"
275→                />
276→              </CardContent>
277→            </Card>
278→          ))}
279→        </TabsContent>
280→
281→        {/* ── Prompt Studio Tab ── */}
282→        <TabsContent value="studio" className="space-y-6">
283→          <div className="flex items-center justify-between">
284→            <div className="flex items-center gap-3">
285→              <Label className="text-sm font-medium">Prompt Type:</Label>
286→              <Select value={studioType} onValueChange={(v) => { setStudioType(v as PromptType); setCompareIds(null); }}>
287→                <SelectTrigger className="w-[180px]"><SelectValue /></SelectTrigger>
288→                <SelectContent>
289→                  {PROMPT_TYPES.map(({ key, label }) => <SelectItem key={key} value={key}>{label}</SelectItem>)}
290→                </SelectContent>
291→              </Select>
292→            </div>
293→            <div className="flex gap-2">
294→              {compareIds ? (
295→                <Button variant="outline" size="sm" onClick={() => setCompareIds(null)}>Exit Compare</Button>
296→              ) : null}
297→              <Button size="sm" onClick={openNewFromCurrent}><Plus className="h-4 w-4 mr-1" />New Version</Button>
298→            </div>
299→          </div>
300→
301→          {/* Sample Input */}
302→          <Card>
303→            <CardHeader className="pb-2"><CardTitle className="text-sm font-medium text-muted-foreground">Test Sample Input</CardTitle></CardHeader>
304→            <CardContent>
305→              <Textarea
306→                value={testInput}
307→                onChange={(e) => setTestInput(e.target.value)}
308→                rows={3} className="font-mono text-xs"
309→                placeholder={SAMPLE_INPUTS[studioType]}
310→              />
311→            </CardContent>
312→          </Card>
313→
314→          {/* Compare View */}
315→          {compareIds && compareVersions.length === 2 ? (
316→            <div className="grid grid-cols-2 gap-4">
317→              {compareVersions.map((v) => (
318→                <Card key={v.id}>
319→                  <CardHeader className="pb-2">
320→                    <div className="flex items-center justify-between">
321→                      <CardTitle className="text-sm">{v.label}</CardTitle>
322→                      {v.is_active && <Badge>Active</Badge>}
323→                    </div>
324→                    <CardDescription className="text-xs">{v.model} · temp {v.temperature}</CardDescription>
325→                  </CardHeader>
326→                  <CardContent className="space-y-3">
327→                    <div>
328→                      <Label className="text-xs text-muted-foreground">Prompt</Label>
329→                      <pre className="text-xs bg-muted p-2 rounded max-h-40 overflow-auto whitespace-pre-wrap">{v.prompt_text}</pre>
330→                    </div>
331→                    {v.test_result_json && (
332→                      <div>
333→                        <Label className="text-xs text-muted-foreground">
334→                          Test Output ({v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens)
335→                        </Label>
336→                        <pre className="text-xs bg-muted p-2 rounded max-h-60 overflow-auto whitespace-pre-wrap">{v.test_result_json.output}</pre>
337→                      </div>
338→                    )}
339→                  </CardContent>
340→                </Card>
341→              ))}
342→            </div>
343→          ) : (
344→            /* Version List */
345→            <div className="space-y-3">
346→              {versionsLoading ? (
347→                <p className="text-sm text-muted-foreground">Loading versions…</p>
348→              ) : versions?.length === 0 ? (
349→                <Card><CardContent className="py-8 text-center text-muted-foreground text-sm">No versions yet. Click "New Version" to create one from the current live prompt.</CardContent></Card>
350→              ) : versions?.map((v) => (
351→                <Card key={v.id} className={v.is_active ? "border-primary/50" : ""}>
352→                  <CardContent className="p-4">
353→                    <div className="flex items-start justify-between gap-4">
354→                      <div className="flex-1 min-w-0">
355→                        <div className="flex items-center gap-2 mb-1">
356→                          <span className="font-medium text-sm">{v.label}</span>
357→                          {v.is_active && <Badge variant="default" className="text-xs">Active</Badge>}
358→                          <span className="text-xs text-muted-foreground">{v.model} · temp {v.temperature}</span>
359→                          <span className="text-xs text-muted-foreground">{new Date(v.created_at).toLocaleDateString()}</span>
360→                        </div>
361→                        {v.notes && <p className="text-xs text-muted-foreground mb-2">{v.notes}</p>}
362→                        <pre className="text-xs bg-muted p-2 rounded max-h-24 overflow-auto whitespace-pre-wrap">{v.prompt_text.slice(0, 300)}{v.prompt_text.length > 300 ? "…" : ""}</pre>
363→                        {v.test_result_json && (
364→                          <div className="mt-2 p-2 bg-muted/50 rounded border">
365→                            <span className="text-xs font-medium">Last test: </span>
366→                            <span className="text-xs text-muted-foreground">
367→                              {v.test_result_json.latency_ms}ms · {v.test_result_json.tokens?.total_tokens} tokens
368→                            </span>
369→                            <pre className="text-xs mt-1 max-h-32 overflow-auto whitespace-pre-wrap">{v.test_result_json.output?.slice(0, 500)}</pre>
370→                          </div>
371→                        )}
372→                      </div>
373→                      <div className="flex flex-col gap-1 shrink-0">
374→                        <Button
375→                          variant="outline" size="sm"
376→                          disabled={testingId === v.id}
377→                          onClick={() => testVersion(v)}
378→                        >
379→                          {testingId === v.id ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <Play className="h-3.5 w-3.5 mr-1" />}
380→                          Test
381→                        </Button>
382→                        {!v.is_active && (
383→                          <Button variant="outline" size="sm" onClick={() => activateVersion(v)}>
384→                            <Star className="h-3.5 w-3.5 mr-1" />Deploy
385→                          </Button>
386→                        )}
387→                        <Button
388→                          variant="ghost" size="sm"
389→                          onClick={() => {
390→                            if (!compareIds) {
391→                              setCompareIds([v.id, ""]);
392→                              toast.info("Select a second version to compare");
393→                            } else if (compareIds[1] === "") {
394→                              setCompareIds([compareIds[0], v.id]);
395→                            }
396→                          }}
397→                        >
398→                          <GitCompare className="h-3.5 w-3.5 mr-1" />Compare
399→                        </Button>
400→                        <Button variant="ghost" size="sm" onClick={() => deleteVersion(v)}>
401→                          <Trash2 className="h-3.5 w-3.5 text-destructive" />
402→                        </Button>
403→                      </div>
404→                    </div>
405→                  </CardContent>
406→                </Card>
407→              ))}
408→            </div>
409→          )}
410→        </TabsContent>
411→
412→        {/* ── Scoring Algorithm Tab ── */}
413→        <TabsContent value="algorithm" className="space-y-6 max-w-3xl">
414→          <Card>
415→            <CardHeader>
416→              <div className="flex items-center justify-between">
417→                <div>
418→                  <CardTitle className="text-lg">Scoring Algorithm</CardTitle>
419→                  <CardDescription>Configure how dimension weights, quality gates, and scoring caps are applied.</CardDescription>
420→                </div>
421→                <Badge variant="outline" className="text-xs">v{config.algorithm_version}</Badge>
422→              </div>
423→            </CardHeader>
424→            <CardContent className="space-y-6">
425→              {/* Weight Strategy */}
426→              <div className="space-y-2">
427→                <Label>Dimension Weight Strategy</Label>
428→                <Select value={config.default_weight_strategy || "priority_boosted"} onValueChange={(v) => updateConfig("default_weight_strategy" as any, v)}>
429→                  <SelectTrigger><SelectValue /></SelectTrigger>
430→                  <SelectContent>
431→                    <SelectItem value="equal">Equal — all dimensions weighted equally</SelectItem>
432→                    <SelectItem value="priority_boosted">Priority Boosted — skill/tool/experience dimensions get 2× weight</SelectItem>
433→                    <SelectItem value="custom">Custom — use manual weight overrides below</SelectItem>
434→                  </SelectContent>
435→                </Select>
436→              </div>
437→
438→              {/* Custom Weight Overrides */}
439→              {(config.default_weight_strategy === "custom") && (
440→                <div className="space-y-3 border rounded-lg p-4">
441→                  <Label className="text-sm font-medium">Weight Overrides</Label>
442→                  <p className="text-xs text-muted-foreground">Set relative weights for common evaluation dimensions. Higher = more influence on overall score.</p>
443→                  {["skill_relevance", "experience_depth", "domain_fit", "tool_familiarity", "seniority_match", "leadership_signals", "education_alignment"].map((dimKey) => {
444→                    const weight = config.weight_overrides_json?.[dimKey] ?? 1.0;
445→                    return (
446→                      <div key={dimKey} className="flex items-center gap-4">
447→                        <span className="text-sm w-40 capitalize">{dimKey.replace(/_/g, " ")}</span>
448→                        <Slider
449→                          value={[weight]}
450→                          onValueChange={([v]) => updateConfig("weight_overrides_json" as any, { ...config.weight_overrides_json, [dimKey]: Math.round(v * 10) / 10 })}
451→                          min={0.1} max={5.0} step={0.1} className="flex-1"
452→                        />
453→                        <span className="text-sm text-muted-foreground w-10 text-right">{weight.toFixed(1)}</span>
454→                      </div>
455→                    );
456→                  })}
457→                </div>
458→              )}
459→
460→              {/* Scoring Caps */}
461→              <div className="grid grid-cols-2 gap-4">
462→                <div className="space-y-2">
463→                  <Label>Hard-Fit Cap</Label>
464→                  <p className="text-xs text-muted-foreground">Max score for candidates missing critical must-haves</p>
465→                  <Input type="number" min={0} max={100} value={config.hard_fit_cap ?? 49} onChange={(e) => updateConfig("hard_fit_cap" as any, parseInt(e.target.value) || 49)} />
466→                </div>
467→                <div className="space-y-2">
468→                  <Label>Algorithm Version</Label>
469→                  <p className="text-xs text-muted-foreground">Auto-tracks scoring config changes</p>
470→                  <Input type="number" min={1} value={config.algorithm_version ?? 1} onChange={(e) => updateConfig("algorithm_version" as any, parseInt(e.target.value) || 1)} />
471→                </div>
472→              </div>
473→
474→              {/* Quality Gates */}
