 72→const synonymToCanonical = new Map<string, string>();
 73→for (const [canonical, synonyms] of Object.entries(SKILL_SYNONYMS)) {
 74→  synonymToCanonical.set(canonical, canonical);
 75→  for (const syn of synonyms) synonymToCanonical.set(syn, canonical);
 76→}
 77→
 78→function normalizeSkill(skill: string): string {
 79→  const lower = skill.toLowerCase().trim().replace(/[.\-\/]/g, '').replace(/\s+/g, ' ');
 80→  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
 81→}
 82→
 83→function tokenize(term: string): string[] {
 84→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
 85→}
 86→
 87→function tokenOverlap(a: string, b: string): number {
 88→  const tokensA = tokenize(a);
 89→  const tokensB = tokenize(b);
 90→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
 91→  const setB = new Set(tokensB);
 92→  const matched = tokensA.filter(t => setB.has(t)).length;
 93→  return matched / Math.max(tokensA.length, tokensB.length);
 94→}
 95→
 96→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
 97→  const normalizedJd = normalizeSkill(jdTerm);
 98→  for (const rt of resumeTerms) {
 99→    const normalizedResume = normalizeSkill(rt);
100→    if (normalizedJd === normalizedResume) return true;
101→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
102→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
103→  }
104→  return false;
105→}
