210→async function processResume(
211→  supabase: any,
212→  resumeId: string,
213→  jobId: string,
214→  userId: string,
215→  cfg: any,
216→  deepScoringPrompt: string | null,
217→  job: any,
218→  jdAnalysis: any,
219→  dynamicWeights: any,
220→  jdEmbedding: any,
221→  dimensions: any[],
222→) {
223→  // Step 1: Call parse-resume to extract text + structured data
224→  console.log(`Parsing resume ${resumeId}...`);
225→  try {
226→    const { data: parseResult, error: parseError } = await supabase.functions.invoke("parse-resume", {
227→      body: { resume_id: resumeId, job_id: jobId },
228→    });
229→    if (parseError) {
230→      console.error(`parse-resume invocation error for ${resumeId}:`, parseError);
231→    } else {
232→      console.log(`Resume ${resumeId} parsed: method=${parseResult?.extraction_method}, chars=${parseResult?.text_length}, sufficient=${parseResult?.sufficient}`);
233→    }
234→  } catch (err) {
235→    console.error(`parse-resume call failed for ${resumeId}:`, err);
236→    await logSystemError({ function_name: "rank-resumes", error_type: "PARSE_INVOKE", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
237→  }
238→
239→  // Step 2: Re-fetch resume after parsing
240→  const { data: resume } = await supabase.from("resumes").select("*").eq("id", resumeId).single();
241→  if (!resume) {
242→    console.error(`Resume ${resumeId} not found after parsing`);
243→    return false;
244→  }
245→
246→  const rawText = resume.parsed_text || "";
247→  const parsedJson = resume.parsed_json;
248→
249→  // Step 3: Check if we have enough content to score
250→  const hasUsefulParsedJson = parsedJson && (
251→    (Array.isArray(parsedJson.skills_with_evidence) && parsedJson.skills_with_evidence.length > 0) ||
252→    (Array.isArray(parsedJson.roles_with_dates) && parsedJson.roles_with_dates.length > 0) ||
253→    (Array.isArray(parsedJson.education) && parsedJson.education.length > 0)
254→  );
255→  if (rawText.trim().length < 50 && !hasUsefulParsedJson) {
256→    console.warn(`Resume ${resumeId}: insufficient content after parsing, inserting zero score`);
257→    const summaryMsg = resume.status === "failed"
258→      ? "Could not extract text from this file. It may be image-based or have unsupported formatting. Please re-upload a text-based PDF or DOCX file."
259→      : "Resume content too short to evaluate. Please re-upload a valid PDF/DOCX.";
260→    const resultData = {
261→      resume_id: resumeId, job_id: jobId, scoring_version: "insufficient",
262→      overall_score: 0, hard_fit: false, confidence: 0,
263→      category_scores_json: {}, strengths_json: [], gaps_json: [],
264→      interview_questions: [], explanation_json: { extraction_failed: true },
265→      matched_must_haves: [], missing_must_haves: [], missing_skills: [],
266→      summary: summaryMsg,
267→      skill_score: null, experience_score: null, education_score: null,
268→    };
269→    const { data: existing } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
270→    if (existing) await supabase.from("results").update(resultData as any).eq("id", existing.id);
271→    else await supabase.from("results").insert(resultData as any);
272→    return false;
273→  }
274→
275→  // Step 4: Deep score with OpenAI
276→  try {
277→    const resumeText = rawText || JSON.stringify(parsedJson || {});
278→    const deepResult = await deepScoreResume(
279→      job.job_description, resumeText, parsedJson,
280→      jdAnalysis, dimensions, cfg, deepScoringPrompt
281→    );
282→
283→    let overallScore = 0;
284→    const categoryScores = deepResult.category_scores || {};
285→
286→    const normalizeKey = (k: string) => k.toLowerCase().replace(/[\s_-]+/g, "_").trim();
287→    const scoreKeyMap = new Map<string, any>();
288→    for (const [k, v] of Object.entries(categoryScores)) {
289→      scoreKeyMap.set(normalizeKey(k), v);
290→    }
291→
292→    for (const dim of dimensions) {
293→      const weight = dynamicWeights[dim.key] ?? 0;
294→      const scoreEntry = categoryScores[dim.key] || scoreKeyMap.get(normalizeKey(dim.key));
295→      overallScore += (scoreEntry?.score ?? 0) * weight;
296→    }
297→
298→    if (overallScore === 0 && Object.keys(categoryScores).length > 0) {
299→      const allScores = Object.values(categoryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
300→      if (allScores.length > 0) overallScore = allScores.reduce((a: number, b: number) => a + b, 0) / allScores.length;
301→    }
302→
303→    overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
304→
305→    // All-zero retry
306→    const allZero = Object.values(categoryScores).every((v: any) => (v?.score ?? 0) === 0);
307→    if (allZero && resumeText.length > 200 && (deepResult.confidence ?? 0) === 0) {
308→      console.warn(`Resume ${resumeId}: all scores=0, retrying once...`);
309→      try {
310→        const retryResult = await deepScoreResume(
311→          job.job_description, resumeText, parsedJson,
312→          jdAnalysis, dimensions, cfg, deepScoringPrompt
313→        );
314→        const retryScores = retryResult.category_scores || {};
315→        const retryAllZero = Object.values(retryScores).every((v: any) => (v?.score ?? 0) === 0);
316→        if (!retryAllZero) {
317→          Object.assign(deepResult, retryResult);
318→          Object.assign(categoryScores, retryScores);
319→          overallScore = 0;
320→          const retryKeyMap = new Map<string, any>();
321→          for (const [k, v] of Object.entries(retryScores)) retryKeyMap.set(normalizeKey(k), v);
322→          for (const dim of dimensions) {
323→            const weight = dynamicWeights[dim.key] ?? 0;
324→            const scoreEntry = retryScores[dim.key] || retryKeyMap.get(normalizeKey(dim.key));
325→            overallScore += (scoreEntry?.score ?? 0) * weight;
326→          }
327→          if (overallScore === 0 && Object.keys(retryScores).length > 0) {
328→            const rs = Object.values(retryScores).map((v: any) => v?.score ?? 0).filter((s: number) => s > 0);
329→            if (rs.length > 0) overallScore = rs.reduce((a: number, b: number) => a + b, 0) / rs.length;
330→          }
331→          overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
332→        }
333→      } catch (retryErr) {
334→        console.error(`Retry scoring failed for ${resumeId}:`, retryErr);
335→      }
336→    }
337→
338→    let hardFit = deepResult.hard_fit !== false;
339→    const missingCritical = deepResult.missing_critical_must_haves || [];
340→    const hardFitCap = cfg.hard_fit_cap ?? 49;
341→    if (missingCritical.length > 0) {
342→      hardFit = false;
343→      overallScore = Math.min(overallScore, hardFitCap);
344→    }
345→
346→    // Update name if scoring found a better one
347→    const bestName = resume.candidate_name;
348→    if (deepResult.candidate_name && deepResult.candidate_name !== "Unknown Candidate") {
349→      await supabase.from("resumes").update({ candidate_name: deepResult.candidate_name, status: "done" }).eq("id", resumeId);
350→    } else {
351→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
352→    }
353→
354→    const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
355→    const resultData = {
356→      resume_id: resumeId, job_id: jobId, scoring_version: `v7-algo${cfg.algorithm_version ?? 1}`,
357→      overall_score: overallScore, hard_fit: hardFit,
358→      confidence: deepResult.confidence ?? 0,
359→      category_scores_json: categoryScores,
360→      strengths_json: deepResult.strengths || [],
361→      gaps_json: deepResult.gaps || [],
362→      interview_questions: deepResult.interview_questions || [],
363→      explanation_json: {
364→        ...(deepResult.explanation || {}),
365→        matched_preferred: deepResult.matched_preferred_must_haves || [],
366→        missing_preferred: deepResult.missing_preferred_must_haves || [],
367→      },
368→      matched_must_haves: deepResult.matched_critical_must_haves || [],
369→      missing_must_haves: missingCritical,
370→      missing_skills: missingCritical,
371→      summary: deepResult.explanation?.summary || "",
372→      skill_score: null, experience_score: null, education_score: null,
373→    };
374→
375→    if (existingResult) {
376→      await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
377→    } else {
378→      await supabase.from("results").insert(resultData as any);
379→    }
380→    console.log(`Resume ${resumeId} scored: overall=${overallScore}, hardFit=${hardFit}`);
381→    return true;
382→
383→  } catch (err) {
384→    console.error(`Deep scoring failed for ${resumeId}, falling back to heuristic:`, err);
385→    await logSystemError({ function_name: "rank-resumes", error_type: "GPT_SCORING", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
386→
387→    // Heuristic fallback
388→    try {
389→      const allResumeTerms = extractResumeTerms(parsedJson);
390→      const mustHaves = jdAnalysis.critical_must_haves || [];
391→      const jdTools = jdAnalysis.tools || [];
392→      const totalKeywords = mustHaves.length + jdTools.length;
393→      let matchedCount = 0;
394→      const matchedSkills: string[] = [];
395→      const missingSkills: string[] = [];
396→
397→      for (const mh of mustHaves) {
398→        if (fuzzyMatch(mh, allResumeTerms)) { matchedCount++; matchedSkills.push(mh); }
399→        else { missingSkills.push(mh); }
400→      }
401→      for (const tool of jdTools) {
402→        if (fuzzyMatch(tool, allResumeTerms)) { matchedCount++; matchedSkills.push(tool); }
403→      }
404→
405→      const keywordScore = totalKeywords > 0 ? (matchedCount / totalKeywords) * 100 : 30;
406→      let similarity = 0.3;
407→      if (jdEmbedding) {
408→        const { data: simResult } = await supabase.rpc("match_resumes_by_embedding", {
409→          query_embedding: jdEmbedding, match_job_id: jobId, match_count: 1,
410→        });
411→        const match = (simResult || []).find((s: any) => s.id === resumeId);
412→        if (match) similarity = match.similarity;
413→      }
414→      let heuristicScore = Math.round(similarity * 100 * 0.6 + keywordScore * 0.4);
415→      const hFit = missingSkills.length === 0;
416→      if (!hFit) heuristicScore = Math.min(heuristicScore, 49);
417→      heuristicScore = Math.max(0, Math.min(100, heuristicScore));
418→
419→      const summary = `AI scoring unavailable — ranked by keyword match (${matchedCount}/${totalKeywords}).`;
420→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
421→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
422→      const resultData = {
423→        resume_id: resumeId, job_id: jobId, scoring_version: "heuristic",
424→        overall_score: heuristicScore, hard_fit: hFit,
425→        confidence: Math.min(Math.round((matchedCount / Math.max(totalKeywords, 1)) * 40), 40),
426→        category_scores_json: {}, strengths_json: matchedSkills.slice(0, 5),
427→        gaps_json: missingSkills.slice(0, 5), interview_questions: [],
428→        explanation_json: { summary }, matched_must_haves: matchedSkills,
429→        missing_must_haves: missingSkills, missing_skills: missingSkills, summary,
430→        skill_score: null, experience_score: null, education_score: null,
431→      };
432→      if (existingResult) await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
433→      else await supabase.from("results").insert(resultData as any);
434→      return true;
435→    } catch (fallbackErr) {
436→      console.error(`Heuristic fallback also failed for ${resumeId}:`, fallbackErr);
437→      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
438→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
439→      if (!existingResult) {
440→        await supabase.from("results").insert({
441→          resume_id: resumeId, job_id: jobId, overall_score: 0, hard_fit: false,
442→          confidence: 0, category_scores_json: {}, strengths_json: [], gaps_json: [],
443→          summary: `Scoring failed: ${err instanceof Error ? err.message : "Unknown error"}`,
444→        } as any);
445→      }
446→      return false;
447→    }
448→  }
449→}
