433→        headers: {
434→          "Content-Type": "application/json",
435→          Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
436→        },
437→        body: JSON.stringify({ job_id: jobId, resume_ids: resumeIds }),
438→      }
439→    );
