454→      if (resumeProgress) {
455→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
456→        setScoredCount(done);
457→        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
458→        setRankingProgress(Math.min(60 + pct, 95));
